<template>
  <section class="page support-admin"><div class="page-heading"><div><span class="kicker">SUPPORT CONSOLE</span><h1>支持后台</h1><p>管理模型、查看用量，维护组织账号与操作记录。</p></div><button class="quiet-button" :disabled="busy" @click="load">刷新后台</button></div>
    <p v-if="notice" class="inline-notice" role="status">{{ notice }}</p>
    <div class="admin-tabs" role="tablist" aria-label="后台功能"><button v-for="tab in tabs" :key="tab.id" role="tab" :aria-selected="activeTab===tab.id" :class="{selected:activeTab===tab.id}" @click="activeTab=tab.id">{{ tab.label }}</button></div>
    <template v-if="activeTab==='models'">
      <section class="workspace-card active-model"><span class="kicker">ACTIVE MODEL</span><h2>{{ models.active?.model || '正在读取配置' }}</h2><p>{{ models.active?.name }} · {{ models.active?.protocol }} · {{ models.active?.base_url }}</p><small>新任务读取当前配置；执行中的任务保留原模型。Key 仅加密保存在服务端，不返回浏览器。</small></section>
      <div class="admin-columns"><section class="workspace-card"><div class="card-heading"><h2>已保存的模型</h2><button class="text-button" @click="resetForm">新增配置</button></div><article v-for="profile in models.profiles || []" :key="profile.id" class="profile-row"><div><strong>{{ profile.name }}</strong><p>{{ profile.protocol }} · {{ profile.model }}</p><small>{{ profile.base_url }}</small><p>{{ profile.configured?'密钥已配置':'尚未配置密钥' }} · {{ profile.currency }}</p></div><div class="profile-actions"><span v-if="models.active?.id===profile.id" class="current-profile">正在使用</span><button v-else class="quiet-button" :disabled="busy" @click="activate(profile)">切换到此模型</button><button class="text-button" :disabled="busy || profile.id==='environment'" @click="edit(profile)">编辑配置</button></div></article></section>
        <section class="workspace-card"><h2>{{ editingId?'编辑模型配置':'新增模型配置' }}</h2><form @submit.prevent="save"><fieldset :disabled="busy"><label>配置名称<input v-model="form.name" required maxlength="100" placeholder="例如：DeepSeek 日常服务" /></label><div class="field-pair"><label>接口协议<select v-model="form.protocol"><option value="openai">OpenAI Chat Completions</option><option value="anthropic">Anthropic Messages</option></select></label><label>模型名称<input v-model="form.model" required maxlength="100" placeholder="供应商提供的模型 ID" /></label></div><label>模型服务地址<input v-model="form.base_url" required type="url" placeholder="https://provider.example/v1" /></label><label>模型 API Key<input v-model="form.api_key" type="password" autocomplete="off" :required="!editingId" :placeholder="editingId?'留空保留现有密钥':'填写自己的模型 API Key'" /></label><div class="pricing-form"><label>费用币种<select v-model="form.currency"><option>CNY</option><option>USD</option></select></label><label>输入单价 / 百万Token<input v-model="form.prices.input" inputmode="decimal" placeholder="未填写则费用未知" /></label><label>输出单价 / 百万Token<input v-model="form.prices.output" inputmode="decimal" placeholder="未填写则费用未知" /></label><label>缓存命中输入单价 / 百万Token<input v-model="form.prices.cached_input" inputmode="decimal" placeholder="未填写则费用未知" /></label></div><p class="muted">单价由你按供应商账户填写。保存新配置不会自动切换；编辑当前配置会影响后续新任务。</p><button type="submit">{{ busy?'正在保存…':'保存模型配置' }}</button></fieldset></form></section></div>
      <section class="workspace-card"><div class="card-heading"><div><span class="kicker">TOKEN USAGE</span><h2>模型用量与费用</h2></div><label class="compact-label">统计范围<select v-model.number="usageDays" @change="load"><option :value="1">近1天</option><option :value="7">近7天</option><option :value="30">近30天</option></select></label></div><div class="usage-cards"><article><span>调用次数</span><strong>{{ usage.calls ?? '—' }}</strong></article><article><span>输入 / 输出 Token</span><strong>{{ usage.input_tokens ?? '—' }} / {{ usage.output_tokens ?? '—' }}</strong></article><article><span>费用未知的调用</span><strong>{{ usage.unknown_cost_calls ?? '—' }}</strong></article><article><span>已知部分估算费用</span><strong v-if="Object.keys(usage.estimated_costs || {}).length"><span v-for="(value,currency) in usage.estimated_costs" :key="currency">{{ currency }} {{ money(value) }} </span></strong><strong v-else>暂无可估算数据</strong></article></div><p class="muted">{{ usage.note || models.pricing_note }}</p><p v-if="usage.truncated" class="inline-notice">当前汇总仅覆盖最近 {{ usage.observed_calls }} 次调用，查询总数为 {{ usage.calls }}，请缩短统计范围。</p><div class="admin-table-scroll"><table><thead><tr><th>时间</th><th>模型 / 账号</th><th>状态</th><th>输入 / 输出</th><th>估算费用</th></tr></thead><tbody><tr v-for="call in usage.recent || []" :key="call.id"><td>{{ date(call.created) }}</td><td>{{ call.model }}<small>{{ call.owner }}</small></td><td>{{ call.status==='completed'?'已完成':call.status==='failed'?'失败 / 费用待核实':'处理中 / 待核实' }}</td><td>{{ call.input_tokens ?? '未知' }} / {{ call.output_tokens ?? '未知' }}</td><td>{{ call.estimated_cost===null?'未知':`${call.currency} ${money(call.estimated_cost)}` }}</td></tr><tr v-if="!usage.recent?.length"><td colspan="5">尚无新运行链的模型调用记录；历史开发账本保留，不混入本页。</td></tr></tbody></table></div></section>
    </template>
    <template v-else-if="activeTab==='accounts'"><div class="admin-columns"><section class="workspace-card"><h2>组织账号</h2><p class="muted">禁用账号会使现有会话失效，并回收系统内有效权限和软件席位。业务记录和审计保留。</p><article v-for="account in accounts" :key="account.user_id" class="profile-row"><div><strong>{{ account.display_name }}</strong><p>{{ account.user_id }} · {{ account.role==='support'?'支持人员':'员工' }} · {{ account.enabled?'启用':'停用' }}</p></div><div class="profile-actions"><button class="quiet-button" :disabled="busy || account.user_id===settings.userId" @click="enable(account)">{{ account.enabled?'停用账号':'启用账号' }}</button><button class="text-button" :disabled="busy" @click="revoke(account)">撤销登录会话</button></div></article></section><section class="workspace-card"><h2>创建账号</h2><form @submit.prevent="createAccount"><fieldset :disabled="busy"><label>账号<input v-model="accountForm.username" required pattern="[A-Za-z0-9_.-]{1,64}" autocomplete="off" /></label><label>显示名称<input v-model="accountForm.display_name" maxlength="100" /></label><label>角色<select v-model="accountForm.role"><option value="user">员工</option><option value="support">支持人员</option></select></label><label>初始密码<input v-model="accountForm.password" required type="password" minlength="10" maxlength="256" autocomplete="new-password" /></label><button type="submit">创建账号</button></fieldset></form></section></div></template>
    <section v-else class="workspace-card"><h2>管理操作审计</h2><div class="admin-table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象</th></tr></thead><tbody><tr v-for="entry in audit" :key="entry.id"><td>{{ date(entry.created) }}</td><td>{{ entry.actor }}</td><td>{{ entry.action }}</td><td>{{ entry.target }}</td></tr></tbody></table></div></section>
  </section>
</template>

<script setup>
import { onMounted,onBeforeUnmount,reactive,ref } from 'vue'
import { deskRequest } from '../lib/resolvedesk.js'
import { createRequestState } from '../lib/requestState.js'
const props=defineProps({settings:{type:Object,required:true}})
const requests=createRequestState(props.settings),models=ref({}),usage=ref({}),accounts=ref([]),audit=ref([]),busy=ref(false),notice=ref(''),activeTab=ref('models'),usageDays=ref(30),editingId=ref(''),editingRevision=ref(null)
const tabs=[{id:'models',label:'模型与用量'},{id:'accounts',label:'账号管理'},{id:'audit',label:'操作审计'}]
const empty=()=>({name:'',protocol:'openai',model:'',base_url:'',api_key:'',currency:'CNY',prices:{input:'',output:'',cached_input:''}})
const form=reactive(empty()),accountForm=reactive({username:'',display_name:'',role:'user',password:''})
const date=value=>new Date(value*1000).toLocaleString(),money=value=>Number(value).toFixed(6)
async function load(){const r=requests.begin('load');try{const data=await Promise.all([deskRequest(r.settings,'/admin/models'),deskRequest(r.settings,`/admin/model-usage?days=${usageDays.value}`),deskRequest(r.settings,'/admin/accounts'),deskRequest(r.settings,'/admin/audit')]);if(r.isCurrent())[models.value,usage.value,accounts.value,audit.value]=data}catch(e){if(r.isCurrent())notice.value=e.message}}
function resetForm(){editingId.value='';editingRevision.value=null;Object.assign(form,empty())}
function edit(profile){editingId.value=profile.id;editingRevision.value=profile.revision;Object.assign(form,{...profile,api_key:'',prices:{...profile.prices}})}
async function mutate(path,method,body,after){const r=requests.begin('mutation');busy.value=true;notice.value='';try{await deskRequest(r.settings,path,method,body);if(!r.isCurrent())return;after?.();notice.value='操作已保存。';await load()}catch(e){if(r.isCurrent())notice.value=e.message}finally{if(r.isCurrent())busy.value=false}}
function save(){const body={name:form.name,protocol:form.protocol,model:form.model,base_url:form.base_url,api_key:form.api_key,currency:form.currency,prices:{...form.prices}};if(editingId.value)body.revision=editingRevision.value;return mutate(editingId.value?`/admin/models/${editingId.value}`:'/admin/models',editingId.value?'PUT':'POST',body,resetForm)}
function activate(profile){return mutate(`/admin/models/${profile.id}/activate`,'POST',{revision:profile.revision})}
function createAccount(){return mutate('/admin/accounts','POST',{...accountForm},()=>{accountForm.password='';accountForm.username='';accountForm.display_name=''})}
function enable(account){return mutate(`/admin/accounts/${account.user_id}`,'PATCH',{enabled:!account.enabled})}
function revoke(account){return mutate(`/admin/accounts/${account.user_id}/revoke-sessions`,'POST')}
onMounted(load)
onBeforeUnmount(()=>{requests.invalidate();form.api_key='';accountForm.password=''})
</script>

<style scoped>
.support-admin{display:grid;gap:20px}.admin-tabs{display:flex;gap:8px;border-bottom:1px solid #e2e7f1;padding-bottom:12px}.admin-tabs button{background:transparent;color:#65718a;box-shadow:none}.admin-tabs .selected{background:#eaf0ff;color:#2f52cb}.admin-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}.active-model h2{font-size:27px;margin:12px 0}.active-model p,.active-model small{overflow-wrap:anywhere;color:#66738a}.profile-row{display:flex;gap:12px;justify-content:space-between;padding:20px 0;border-bottom:1px solid #e5eaf3}.profile-row p{font-size:13px;color:#65718a;margin:8px 0}.profile-row small{display:block;overflow-wrap:anywhere;max-width:320px;color:#7a869b}.profile-actions{display:flex;flex-direction:column;align-items:flex-end;gap:10px;flex-shrink:0}.current-profile{font-size:12px;background:#e6f6ed;color:#21734c;padding:6px 10px;border-radius:20px}.support-admin form fieldset{display:grid;gap:16px;border:0;padding:0;margin:20px 0 0}.support-admin label{display:grid;gap:7px;font-size:13px}.support-admin input,.support-admin select{padding:10px 12px;border-radius:8px;border:1px solid #dce2ed;background:#fff;min-width:0;width:100%;box-sizing:border-box}.field-pair,.pricing-form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.usage-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.usage-cards article{padding:18px;background:#f5f7fc;border-radius:10px}.usage-cards article>span{font-size:12px;color:#738099}.usage-cards strong{display:block;font-size:19px;margin-top:10px;overflow-wrap:anywhere}.usage-cards strong span{display:block}.admin-table-scroll{overflow-x:auto;margin-top:20px}.support-admin table{border-collapse:collapse;width:100%;font-size:13px;text-align:left}.support-admin th,.support-admin td{padding:14px 12px;border-bottom:1px solid #e6eaf3;white-space:nowrap}.support-admin td small{display:block;color:#7b879a;margin-top:4px}.compact-label{display:flex!important;align-items:center}.support-admin .muted{font-size:13px;line-height:1.8}@media(max-width:1100px){.admin-columns{grid-template-columns:1fr}.usage-cards{grid-template-columns:1fr 1fr}}@media(max-width:600px){.pricing-form,.field-pair{grid-template-columns:1fr}.profile-row{flex-direction:column}.profile-actions{flex-direction:row;align-items:center}.support-admin .workspace-card{padding:20px}}
</style>
